using System;using System.IO;using System.Linq;using System.Drawing;using System.Drawing.Imaging;using System.Collections.Generic;
public static class K052 {
 public static Dictionary<int,int> Hist(string[] files){var d=new Dictionary<int,int>();foreach(var f in files)using(var b=new Bitmap(f)){for(int y=0;y<b.Height;y++)for(int x=0;x<b.Width;x++){var c=b.GetPixel(x,y);if(c.A<250)continue;int k=c.ToArgb()|unchecked((int)0xff000000);if(!d.ContainsKey(k))d[k]=0;d[k]++;}}return d;}
 public static string Hex(int k){return "#"+(k&0xffffff).ToString("X6");}
 public static string[] Palette(string[] files,string[] targets){var d=Hist(files);return targets.Select(t=>{var c=ColorTranslator.FromHtml(t);return Hex(d.Where(p=>p.Value>=8).OrderBy(p=>Dist(c,Color.FromArgb(p.Key))).First().Key);}).Distinct().ToArray();}
 static int Dist(Color a,Color b){return (a.R-b.R)*(a.R-b.R)+(a.G-b.G)*(a.G-b.G)+(a.B-b.B)*(a.B-b.B);}
 public static Bitmap Crop(Bitmap b,int x,int y,int w,int h){return b.Clone(new Rectangle(x,y,w,h),PixelFormat.Format32bppArgb);}
 public static Rectangle Bounds(Bitmap b){int l=b.Width,t=b.Height,r=-1,d=-1;for(int y=0;y<b.Height;y++)for(int x=0;x<b.Width;x++)if(b.GetPixel(x,y).A>128){l=Math.Min(l,x);r=Math.Max(r,x);t=Math.Min(t,y);d=Math.Max(d,y);}return r<l?Rectangle.Empty:Rectangle.FromLTRB(l,t,r+1,d+1);}
 public static Bitmap Resize(Bitmap b,int w,int h){var o=new Bitmap(w,h);for(int y=0;y<h;y++)for(int x=0;x<w;x++)o.SetPixel(x,y,b.GetPixel(Math.Min(b.Width-1,x*b.Width/w),Math.Min(b.Height-1,y*b.Height/h)));return o;}
 public static void Paste(Bitmap a,Bitmap b,int x,int y){using(var g=Graphics.FromImage(a))g.DrawImageUnscaled(b,x,y);}
 public static Bitmap Quant(Bitmap b,string[] hex){var p=hex.Select(ColorTranslator.FromHtml).ToArray();var o=new Bitmap(b.Width,b.Height);for(int y=0;y<b.Height;y++)for(int x=0;x<b.Width;x++){var c=b.GetPixel(x,y);if(c.A<128)continue;o.SetPixel(x,y,p.OrderBy(z=>Dist(c,z)).First());}return o;}
 public static void Save(Bitmap b,string p){for(int y=0;y<b.Height;y++)for(int x=0;x<b.Width;x++)if(b.GetPixel(x,y).A==0)b.SetPixel(x,y,Color.FromArgb(0,0,0,0));b.Save(p,ImageFormat.Png);}
 public static string Outline(Bitmap b){var runs=new List<int>();for(int y=0;y<b.Height;y++){int l=-1,r=-1;for(int x=0;x<b.Width;x++)if(b.GetPixel(x,y).A>128){if(l<0)l=x;r=x;}if(r-l<25)continue;foreach(int s in new int[]{1,-1}){int x=s==1?l:r,n=0;while(x>=0&&x<b.Width&&n<15){var c=b.GetPixel(x,y);if(c.A<128||Math.Max(c.R,Math.Max(c.G,c.B))>48)break;n++;x+=s;}if(n>0&&n<15)runs.Add(n);}}runs.Sort();return runs.Count==0?"없음": "표본 "+runs.Count+", 중앙값 "+runs[runs.Count/2]+"px, 25~75% "+runs[runs.Count/4]+"~"+runs[runs.Count*3/4]+"px";}
 public static Bitmap Poly(Bitmap b,int[] coords){var o=new Bitmap(b.Width,b.Height);var ps=new Point[coords.Length/2];for(int i=0;i<ps.Length;i++)ps[i]=new Point(coords[i*2],coords[i*2+1]);using(var path=new System.Drawing.Drawing2D.GraphicsPath()){path.AddPolygon(ps);for(int y=0;y<b.Height;y++)for(int x=0;x<b.Width;x++)if(path.IsVisible(x,y))o.SetPixel(x,y,b.GetPixel(x,y));}return o;}
 public static Bitmap StretchX(Bitmap b,int split,int leftW,int rightW,int height){var a=Resize(Crop(b,0,0,split,b.Height),leftW,height);var c=Resize(Crop(b,split,0,b.Width-split,b.Height),rightW,height);var o=new Bitmap(leftW+rightW,height);Paste(o,a,0,0);Paste(o,c,leftW,0);return o;}
 public static void Clean(Bitmap b){int w=b.Width,h=b.Height;var seen=new bool[w*h];var q=new Queue<int>();var parts=new List<List<int>>();for(int y=0;y<h;y++)for(int x=0;x<w;x++){int i=y*w+x;if(seen[i]||b.GetPixel(x,y).A<128)continue;var part=new List<int>();seen[i]=true;q.Enqueue(i);while(q.Count>0){int z=q.Dequeue();part.Add(z);int xx=z%w,yy=z/w;for(int dy=-1;dy<=1;dy++)for(int dx=-1;dx<=1;dx++){int nx=xx+dx,ny=yy+dy,ni=ny*w+nx;if(nx<0||ny<0||nx>=w||ny>=h||seen[ni]||b.GetPixel(nx,ny).A<128)continue;seen[ni]=true;q.Enqueue(ni);}}parts.Add(part);}foreach(var part in parts.Where(t=>t.Count<8))foreach(int i in part)b.SetPixel(i%w,i/w,Color.Transparent);}
 public static int Sole(Bitmap b){var r=Bounds(b);var a=new List<int>();for(int x=0;x<b.Width;x++){bool ok=false;for(int y=r.Bottom-2;y<r.Bottom;y++)if(b.GetPixel(x,y).A>128)ok=true;if(ok)a.Add(x);}return a.Count==0?128:a[a.Count/2];} public static Bitmap Disc(Bitmap b){var o=new Bitmap(b.Width,b.Height);for(int y=0;y<b.Height;y++)for(int x=0;x<b.Width;x++){double dx=(x-(b.Width-1)/2.0)/(b.Width/2.0),dy=(y-(b.Height-1)/2.0)/(b.Height/2.0);if(dx*dx+dy*dy<=1)o.SetPixel(x,y,b.GetPixel(x,y));}return o;}
 public static void EraseDisc(Bitmap b,int cx,int cy,int r){for(int y=Math.Max(0,cy-r);y<Math.Min(b.Height,cy+r);y++)for(int x=Math.Max(0,cx-r);x<Math.Min(b.Width,cx+r);x++)if((x-cx)*(x-cx)+(y-cy)*(y-cy)<=r*r)b.SetPixel(x,y,Color.Transparent);}
 public static Bitmap Eye(Bitmap b){var o=(Bitmap)b.Clone();var skin=ColorTranslator.FromHtml("#F9B180");var dark=ColorTranslator.FromHtml("#3A3038");var r=Bounds(b);int xmin=r.X+22,xmax=r.X+60,ymin=r.Y+50,ymax=r.Y+90;var pts=new List<Point>();for(int y=ymin;y<Math.Min(ymax,b.Height);y++)for(int x=xmin;x<Math.Min(xmax,b.Width);x++){var c=b.GetPixel(x,y);if(c.A>128&&c.R<30&&c.G<30&&c.B<48){int count=0;foreach(int dy in new int[]{-2,2})foreach(int dx in new int[]{-2,2}){int xx=x+dx,yy=y+dy;if(xx>=0&&yy>=0&&xx<b.Width&&yy<b.Height){var a=b.GetPixel(xx,yy);if(a.R>170&&a.G>100)count++;}}if(count>=2)pts.Add(new Point(x,y));}}if(pts.Count>0){int cx=(int)pts.Average(p=>p.X),cy=(int)pts.Average(p=>p.Y);for(int yy=pts.Min(p=>p.Y);yy<=pts.Max(p=>p.Y);yy++)for(int xx=pts.Min(p=>p.X);xx<=pts.Max(p=>p.X);xx++)o.SetPixel(xx,yy,skin);for(int x=cx-1;x<=cx+1;x++){o.SetPixel(x,cy,dark);o.SetPixel(x,cy+1,dark);}}return o;} public static int BodyTop(Bitmap b){for(int y=0;y<b.Height;y++)for(int x=b.Width*45/100;x<b.Width*85/100;x++){var c=b.GetPixel(x,y);if(c.A>128&&c.R<100&&c.G<100&&c.B<100)return y;}return Bounds(b).Top;}
 public static Point Hot(Bitmap b,int top){var pts=new List<Point>();for(int y=0;y<Math.Min(b.Height,top+150);y++)for(int x=0;x<b.Width/2;x++){var c=b.GetPixel(x,y);if(c.A>128&&c.R>230&&c.G>150&&c.B<85)pts.Add(new Point(x,y));}return pts.Count==0?new Point(-1,-1):new Point((int)pts.Average(p=>p.X),(int)pts.Average(p=>p.Y));}
 public static void Line(Bitmap b,int x0,int y0,int x1,int y1,string hex,int width){using(var g=Graphics.FromImage(b))using(var p=new Pen(ColorTranslator.FromHtml(hex),width)){g.SmoothingMode=System.Drawing.Drawing2D.SmoothingMode.None;g.DrawLine(p,x0,y0,x1,y1);}}public static string[] FlamePalette(string[] files,string[] targets){var d=Hist(files);return targets.Select(t=>Hex(d.OrderBy(p=>Dist(ColorTranslator.FromHtml(t),Color.FromArgb(p.Key))).First().Key)).Distinct().ToArray();} public static Point Hand(Bitmap b,bool right){var pts=new List<Point>();for(int y=230;y<275;y++)for(int x=0;x<b.Width;x++){var c=b.GetPixel(x,y);if(c.A>128&&c.R>c.G*1.2&&c.G>20&&c.G<120)pts.Add(new Point(x,y));}if(pts.Count==0)return new Point(192,250);int edge=right?pts.Max(p=>p.X):pts.Min(p=>p.X);var q=pts.Where(p=>Math.Abs(p.X-edge)<8).ToArray();return new Point((int)q.Average(p=>p.X),(int)q.Average(p=>p.Y));} public static void ThinOutline(Bitmap b,int max){for(int y=0;y<b.Height;y++){int l=-1,r=-1;for(int x=0;x<b.Width;x++)if(b.GetPixel(x,y).A>128){if(l<0)l=x;r=x;}if(l<0)continue;foreach(int sign in new int[]{1,-1}){int start=sign==1?l:r,n=0;while(start+sign*n>=0&&start+sign*n<b.Width){var c=b.GetPixel(start+sign*n,y);if(c.A<128||Math.Max(c.R,Math.Max(c.G,c.B))>48)break;n++;if(n>=15)break;}if(n>max&&n<15){var c=b.GetPixel(start+sign*n,y);if(c.A<128)continue;for(int i=max;i<n;i++)b.SetPixel(start+sign*i,y,c);}}}}
 public static string[] Used(string[] paths){return Hist(paths).OrderByDescending(p=>p.Value).Select(p=>Hex(p.Key)).ToArray();}
 public static void Label(Bitmap b,string text,int x,int y,int size){using(var g=Graphics.FromImage(b))using(var f=new Font("맑은 고딕",size))using(var brush=new SolidBrush(Color.FromArgb(232,226,212)))g.DrawString(text,f,brush,x,y);}
 public static Bitmap Board(int w,int h){var b=new Bitmap(w,h);using(var g=Graphics.FromImage(b))g.Clear(Color.FromArgb(35,51,44));return b;}public static void Feet(Bitmap b,Bitmap first){for(int y=285;y<b.Height;y++)for(int x=0;x<b.Width;x++)b.SetPixel(x,y,first.GetPixel(x,y));}public static Bitmap LoadCopy(string p){using(var raw=new Bitmap(p)){var b=new Bitmap(raw.Width,raw.Height);Paste(b,raw,0,0);return b;}}public static Bitmap Rotate(Bitmap b,double a){var o=new Bitmap(b.Width,b.Height);double c=(b.Width-1)/2.0,co=Math.Cos(a),si=Math.Sin(a);for(int y=0;y<b.Height;y++)for(int x=0;x<b.Width;x++){int sx=(int)Math.Round(co*(x-c)+si*(y-c)+c),sy=(int)Math.Round(-si*(x-c)+co*(y-c)+c);if(sx>=0&&sy>=0&&sx<b.Width&&sy<b.Height)o.SetPixel(x,y,b.GetPixel(sx,sy));}return o;} public static bool SameFeet(Bitmap a,Bitmap b){for(int y=285;y<384;y++)for(int x=0;x<384;x++)if(a.GetPixel(x,y).ToArgb()!=b.GetPixel(x,y).ToArgb())return false;return true;}}












